import { Component, h, Host, Prop, Element, Event, type ComponentInterface, type EventEmitter } from '@stencil/core';
import { Consume } from '@src/framework/runtime-context';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { Vue2ValueFix } from '@src/framework/decorators';
import { SegmentedControlContext, type SegmentedControlContextValue } from './context';

const PREFIX = 'segmented-control-item';

/**
 * @slot default - Use the default slot to provide the segmented item label or icon.
 * @part base - The base part.
 */
@Component({
  tag: 'ks-segmented-control-item',
  styleUrl: 'styles/ks-segmented-control-item.scss',
  shadow: true,
})
export class KsSegmentedControlItem implements ComponentInterface {
  @Element() el!: HTMLKsSegmentedControlItemElement;

  @Consume({ context: SegmentedControlContext, subscribe: true }) private context?: SegmentedControlContextValue;

  /**
   * Indicates whether this specific item is disabled. If the parent `ks-segmented-control` is disabled, this item will
   * also be disabled regardless of this prop's value.
   */
  @Prop() disabled = false;
  /** The unique value associated with this segmented item. This value is used to identify the item within the group. */
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Prop() @Vue2ValueFix() value: string | number;
  /** @deprecated Use `value` instead. */
  @Prop() selected = false;

  /** @deprecated Use `change` event on `ks-segmented-group` instead. */
  @Event({ bubbles: false, composed: false }) ksClick!: EventEmitter<string | number>;

  constructor() {
    registerPluginManager(this.el);
  }

  private handleClick = () => {
    if (this.context?.disabled || this.disabled) return;

    this.context?.updateValue?.(this.value);
  };

  render() {
    const { value, disabled } = this;
    const { value: groupValue = '', disabled: groupDisabled = false } = this.context || {};

    return (
      <Host class="KsSegmentedControlItem" ks-active={groupValue === value} ks-disabled={groupDisabled || disabled}>
        <label part="base" class={PREFIX} onClick={this.handleClick} data-testid="ks-segmented-item-index-oLb7CD">
          <slot />
        </label>
      </Host>
    );
  }
}
